  function injectDisclaimer() {
    const fabRoot = document.getElementById('fab-root');
    if (!fabRoot || !fabRoot.shadowRoot) return false;
    const shadow = fabRoot.shadowRoot;
    if (shadow.getElementById('bp-disclaimer-pinned')) return true;
    const container = shadow.querySelector('.bpContainer');
    const messageList = shadow.querySelector('.bpMessageListContainer');
    if (!container || !messageList) return false;
    const wrapper = document.createElement('div');
    wrapper.innerHTML = DISCLAIMER_HTML;
    container.appendChild(wrapper.firstElementChild);
    messageList.style.paddingTop = '60px';
    return true;
  }
  const interval = setInterval(() => {
    if (injectDisclaimer()) {
      clearInterval(interval);
      const fabRoot = document.getElementById('fab-root');
      if (fabRoot && fabRoot.shadowRoot) {
        new MutationObserver(() => injectDisclaimer())
          .observe(fabRoot.shadowRoot, { childList: true, subtree: true });
      }
    }
  }, 300);

  /* ---------- 4. Geo lookup (geo only, no raw IP stored) ---------- */
  let cachedGeo = null;
  async function getGeo() {
    if (cachedGeo) return cachedGeo;
    try {
      const res = await fetch("https://ipwho.is/?fields=success,city,region,country,country_code");
      const d = await res.json();
      cachedGeo = (!d || d.success === false) ? {} : {
        geo_city:    d.city         || "",
        geo_region:  d.region       || "",
        geo_country: d.country      || "",
        geo_cc:      d.country_code || ""   // ISO-2, e.g. ES, FR, PK
      };
    } catch (e) { console.warn("[BP] geo failed:", e); cachedGeo = {}; }
    return cachedGeo;
  }

  /* ---------- 5. Persistent user + save language & geo ---------- */
  async function syncUserData() {
    // Stable userKey so the SAME user is reused on every load (stops new-user churn)
    let key = localStorage.getItem("bp_userKey");
    if (!key) {
      key = (crypto.randomUUID && crypto.randomUUID()) ||
            (Date.now() + "-" + Math.random().toString(36).slice(2));
      localStorage.setItem("bp_userKey", key);
    }

    const base = { pageURL: window.location.href, pageLanguage: LANG };
    const geo  = await getGeo();
    const full = { ...base, ...geo };

    await window.botpress.updateUser({ userKey: key, data: full });
    window.botpress.sendEvent({ type: "custom:setLanguageAndUrl", payload: full });
    console.log("[BP] synced:", key, full);
  }

  window.botpress.on("webchat:initialized", syncUserData);
  window.botpress.on("webchat:ready", syncUserData);
})();

